<template><component :is="admin?AdminLayout:SellerLayout"><main class="management-page banner-workspace"><h1>{{ admin?'Quản lý chiến dịch banner':'Cạnh tranh vị trí banner' }}</h1><p class="banner-notice">Ngân sách dùng credit nội bộ, không phải tiền thật. Mỗi Seller có một bid cố định mỗi chiến dịch; cao nhất thắng, bằng điểm ưu tiên thời gian trước rồi mã bid nhỏ hơn. Chỉ bid được Admin duyệt và sản phẩm đủ điều kiện tham gia.</p><RouterLink class="text-link" to="/banner-credits">Xem ví và lịch sử credit</RouterLink><p v-if="loading" role="status">Đang tải…</p><div v-if="error" class="management-error" role="alert">{{ error }} <button class="button button-outline" :disabled="busy" @click="load()">Tải lại</button></div><p v-if="success" role="status">{{ success }}</p>
  <section v-if="admin" class="market-panel"><h2>Tạo chiến dịch</h2><details><summary>Thêm vị trí banner</summary><form class="management-form" @submit.prevent="createSlot"><label class="management-field">Tên vị trí<input v-model="slotName" required maxlength="120" :disabled="busy"/></label><button class="button button-outline" :disabled="busy">Thêm vị trí</button></form></details><form class="management-form" @submit.prevent="createCampaign"><label class="management-field">Vị trí<select v-model="campaign.slotId" required :disabled="busy"><option value="">Chọn vị trí</option><option v-for="s in slots" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label class="management-field">Tên chiến dịch<input v-model="campaign.title" required maxlength="180" :disabled="busy"/></label><label class="management-field">Hạn gửi bid (giờ máy hiện tại)<input v-model="campaign.biddingEndsAt" type="datetime-local" step="1" required :disabled="busy"/></label><label class="management-field">Bắt đầu hiển thị<input v-model="campaign.startsAt" type="datetime-local" step="1" required :disabled="busy"/></label><label class="management-field">Kết thúc hiển thị<input v-model="campaign.endsAt" type="datetime-local" step="1" required :disabled="busy"/></label><label class="management-field">Bid tối thiểu (credit)<input v-model="campaign.minimumBid" type="number" min="1" max="1000000" step="1" required :disabled="busy"/></label><button class="button button-primary" :disabled="busy">Tạo chiến dịch có lịch</button></form><button class="button button-outline" :disabled="busy" @click="expire">Đối chiếu chiến dịch đã hết hạn</button></section>
  <section><h2>Chiến dịch</h2><div class="banner-campaign-grid"><article v-for="c in list?.content||[]" :key="c.id" class="market-panel"><h3>{{ c.title }}</h3><p>{{ c.slotName }} · {{ campaignLabels[c.status] }}</p><p>Hạn bid: {{ time(c.biddingEndsAt) }}</p><p>Hiển thị: {{ time(c.startsAt) }} → {{ time(c.endsAt) }}</p><p>Tối thiểu {{ c.minimumBid }} credit</p><button class="button button-outline" :disabled="busy" @click="open(c.id)">Chi tiết và kết quả</button></article></div><p v-if="list&&!list.content.length">Chưa có chiến dịch. Không có sản phẩm nào được gán thắng tự động.</p><nav v-if="list" aria-label="Phân trang chiến dịch"><button class="button button-outline" :disabled="loading||list.page===0" @click="load(list.page-1)">Trang trước</button><span>Trang {{ list.page+1 }}</span><button class="button button-outline" :disabled="loading||list.page+1>=list.totalPages" @click="load(list.page+1)">Trang sau</button></nav></section>
  <section v-if="detail" class="market-panel" id="banner-campaign-detail" tabindex="-1"><h2>{{ detail.campaign.title }}</h2><p>{{ campaignLabels[detail.campaign.status] }} · Hạn bid {{ time(detail.campaign.biddingEndsAt) }}</p><p>Credit được giữ khi gửi bid. Bên thua, rút hoặc bị từ chối được giải phóng. Credit của winner được sử dụng khi chiến dịch kết thúc; hủy chiến dịch giải phóng credit đang giữ.</p>
    <form v-if="!admin&&!detail.bids.length&&detail.campaign.status==='OPEN'" class="management-form" @submit.prevent="bid"><label class="management-field">Tìm sản phẩm của gian hàng<input v-model="productSearch" type="search" maxlength="160" :disabled="busy"/></label><button class="button button-outline" type="button" @click="loadProducts">Tìm sản phẩm đủ điều kiện</button><label class="management-field">Sản phẩm<select v-model="bidForm.productId" required :disabled="busy"><option value="">Chọn sản phẩm</option><option v-for="p in products" :key="p.productId" :value="p.productId">{{ p.name }}</option></select></label><label class="management-field">Bid (credit nội bộ)<input v-model="bidForm.credits" type="number" :min="detail.campaign.minimumBid" max="1000000" step="1" required :disabled="busy"/></label><button class="button button-primary" :disabled="busy">Gửi bid và giữ credit</button></form>
    <label class="management-field" v-if="admin">Lý do kiểm duyệt/chốt/hủy<textarea v-model="reason" minlength="8" maxlength="1000" :disabled="busy"/></label>
    <h3>{{ admin?'Các bid':'Bid của bạn' }}</h3><article v-for="b in detail.bids" :key="b.id" class="banner-bid"><h4>{{ b.productName }}</h4><p>{{ b.amount }} credit · {{ bidLabels[b.status] }} · {{ b.approved?'Đã duyệt':'Chưa duyệt' }}</p><div v-if="admin&&detail.campaign.status==='OPEN'&&b.status==='RESERVED'"><button class="button button-outline" :disabled="busy||reason.trim().length<8" @click="decision('bids/'+b.id+'/approve')">Duyệt bid</button><button class="button button-outline" :disabled="busy||reason.trim().length<8" @click="decision('bids/'+b.id+'/reject')">Từ chối và giải phóng credit</button></div><button v-if="!admin&&b.status==='RESERVED'&&detail.campaign.status==='OPEN'" class="button button-outline" :disabled="busy" @click="withdraw(b.id)">Rút bid</button></article><p v-if="!detail.bids.length">Chưa có bid.</p>
    <div v-if="admin"><button class="button button-primary" :disabled="busy||reason.trim().length<8||detail.campaign.status!=='OPEN'" @click="decision('settle')">Chốt winner theo thứ hạng</button><button class="button button-outline" :disabled="busy||reason.trim().length<8||['EXPIRED','CANCELLED'].includes(detail.campaign.status)" @click="decision('cancel')">Hủy chiến dịch và giải phóng credit</button></div>
    <h3>Thứ hạng đủ điều kiện</h3><ol><li v-for="(r,index) in detail.ranking" :key="index">{{ r.productName }} · {{ r.credits }} credit {{ r.own?'· Bid của bạn':'' }}</li></ol><p v-if="!detail.ranking.length">Chưa có bid đã duyệt còn đủ điều kiện.</p><h3>Nhật ký chiến dịch</h3><ul><li v-for="(a,index) in detail.audit" :key="index">{{ a.reason }}</li></ul>
  </section>
</main></component></template>
<script setup>
import {ref,computed,onMounted,nextTick} from 'vue';import {useRoute} from 'vue-router';import AdminLayout from '../../layouts/AdminLayout.vue';import SellerLayout from './Seller/SellerLayout.vue';import {marketplaceRequest as request} from '../../services/marketplace.js';
const route=useRoute(),admin=computed(()=>route.path.startsWith('/admin')),scope=computed(()=>admin.value?'admin':'seller'),list=ref(null),slots=ref([]),detail=ref(null),products=ref([]),productSearch=ref(''),loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),slotName=ref(''),reason=ref(''),campaign=ref({slotId:'',title:'',biddingEndsAt:'',startsAt:'',endsAt:'',minimumBid:''}),bidForm=ref({productId:'',credits:''}),campaignKey=ref(crypto.randomUUID()),bidKey=ref(crypto.randomUUID());
const campaignLabels={OPEN:'Đang nhận và duyệt bid',SCHEDULED:'Đã chốt, hiển thị theo lịch',EXPIRED:'Đã hết hạn',CANCELLED:'Đã hủy'},bidLabels={RESERVED:'Đang giữ credit',WITHDRAWN:'Đã rút',REJECTED:'Bị từ chối',LOST:'Không thắng',WON:'Thắng chiến dịch',RELEASED:'Đã giải phóng'},time=v=>new Date(v+'Z').toLocaleString('vi-VN');
async function load(page=list.value?.page||0){loading.value=true;error.value='';try{[list.value,slots.value]=await Promise.all([request('/'+scope.value+'/banner-campaigns?page='+page),request('/'+scope.value+'/banner-slots')]);}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function open(id){error.value='';try{detail.value=await request('/'+scope.value+'/banner-campaigns/'+id);bidKey.value=crypto.randomUUID();bidForm.value={productId:'',credits:''};if(!admin.value)await loadProducts();await nextTick();document.querySelector('#banner-campaign-detail')?.focus();}catch(e){error.value=e.message;}}
async function loadProducts(){try{products.value=(await request('/seller/inventory?status=ACTIVE&stock=available&size=50&search='+encodeURIComponent(productSearch.value))).content;}catch(e){error.value=e.message;}}
async function command(fn){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn();success.value='Đã ghi nhận từ máy chủ.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
function createSlot(){return command(async()=>{await request('/admin/banner-slots','POST',{name:slotName.value});slotName.value='';await load();});}
function createCampaign(){return command(async()=>{const body={...campaign.value,slotId:Number(campaign.value.slotId),minimumBid:Number(campaign.value.minimumBid),requestKey:campaignKey.value};for(const k of ['biddingEndsAt','startsAt','endsAt'])body[k]=new Date(body[k]).toISOString();detail.value=await request('/admin/banner-campaigns','POST',body);campaignKey.value=crypto.randomUUID();await load();});}
function bid(){return command(async()=>{detail.value=await request('/seller/banner-campaigns/'+detail.value.campaign.id+'/bids','POST',{productId:Number(bidForm.value.productId),credits:Number(bidForm.value.credits),requestKey:bidKey.value});await load();});}
function withdraw(id){return command(async()=>{detail.value=await request('/seller/banner-campaigns/'+detail.value.campaign.id+'/bids/'+id+'/withdraw','POST',{});await load();});}
function decision(action){return command(async()=>{detail.value=await request('/admin/banner-campaigns/'+detail.value.campaign.id+'/'+action,'POST',{revision:detail.value.campaign.revision,reason:reason.value});await load();});}
function expire(){return command(async()=>{await request('/admin/banner-campaigns/expire','POST',{});await load();if(detail.value)await open(detail.value.campaign.id);});}
onMounted(load);
</script>
<style scoped>.banner-workspace>section{margin-top:var(--bm-space-6)}.banner-notice{line-height:1.75;background:var(--bm-soft);padding:var(--bm-space-4);border-radius:var(--bm-radius)}.banner-campaign-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:var(--bm-space-4)}.banner-bid{padding-block:var(--bm-space-4);border-bottom:1px solid var(--bm-border)}.banner-workspace nav{display:flex;align-items:center;gap:20px;margin-block:24px}.banner-workspace button,.banner-workspace .button{margin:4px}.banner-workspace>section>label{display:grid;gap:8px}.banner-workspace textarea{min-height:90px;padding:12px;font:inherit}.banner-workspace :focus-visible{outline:3px solid var(--bm-focus);outline-offset:3px}</style>
